/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.css3;import page2020.view.Value;public class C3content {	public static final class Attr {		public static final String width = "width";		public static final String minWidth = "min-width";		public static final String maxWidth = "max-width";		public static final String height = "height";		public static final String minHeight = "min-height";		public static final String maxHeight = "max-height";			}	public Value width(String pixels) {		return new Value().name(Attr.width).text(pixels);	}	public Value minWidth(String pixels) {		return new Value().name(Attr.minWidth).text(pixels);	}	public Value maxWidth(String pixels) {		return new Value().name(Attr.maxWidth).text(pixels);	}	public Value height(String pixels) {		return new Value().name(Attr.height).text(pixels);	}	public Value minHeight(String pixels) {		return new Value().name(Attr.minHeight).text(pixels);	}	public Value maxHeight(String pixels) {		return new Value().name(Attr.maxHeight).text(pixels);	}}